<template>
	<view class="test-container">
		<!-- 顶部导航区域 -->
		<view style="display: flex; justify-content: center;align-items: center;padding: 0 20rpx; margin-top: 15px">
			<text ><text style="font-weight: 800;font-size: 1.25rem;">{{initCurrentIndex + 1}}</text>/{{resultObj.total}}</text>
			<!-- #ifdef MP-WEIXIN -->
			<progress style="width: calc(100% - 80px);margin-left: 5px;" :percent="precentData" stroke-width="10" border-radius='10' color="#f9df34" />
			<!-- #endif -->
			<!-- #ifdef MP-TOUTIAO -->
			<progress style="width: calc(100% - 80px);margin-left: 5px;border-radius: 10px;" :percent="precentData" stroke-width="10" active-color="#f9df34" background-color="#ebebeb" />
			<!-- #endif -->
		</view>
		<NavBar
				v-if="weixinbar"
		   :title="navTitle"
		   @back="onClickBack" />
		
		 <!-- 主内容区域 -->
		 <view class="content-container">
		   <SwiperLimitLoad
				id="swiperLoad"
		     ref="swiperRef"
		     :current="initCurrentIndex"
		     :duration="swiperDuration"
		     :total="resultObj.total"
		     @transition="swiperTransitionEvent"
		     @change="swiperChangeEvent">
		     <template v-slot:content="{ listData }">
		       <TopicInfo
		         :topicInfo="listData"
		         :answerMode="1"
		         :isAnalysis="false"
		         @selected="postSelectCallBack" />
		     </template>
		   </SwiperLimitLoad>
		 </view>
		
		 <view class="button-container">
		   <!-- 如果当前到达第一题则禁用上一题按钮 -->
		   <button
			 v-if="initCurrentIndex === 0"
		     :disabled="initCurrentIndex === 0"
		     @click="onClickPrevious">
		     上一题
		   </button>
			 <button
				 v-else
			   style="background-color: #f40; color: #ffffff;"
			   @click="onClickPrevious">
			   上一题
			 </button>
		
		   <!-- <button @click="onClickAnswerSheet">答题卡</button> -->
		
		   <!-- 如果当前到达最后一题则禁用下一题按钮 -->
		   <button
			 style="background-color: #f8df2d;color: #ffffff;"
				v-if="initCurrentIndex !== resultObj.total - 1"
		     @click="onClickNext">
		     下一题
		   </button>
			  <button
					v-else
			    class="submit-btn"
			    type="primary"
			    @tap="onClickSubmit">
			    提交答案
			  </button>
		 </view>
	</view>
</template>

<script>
	// 导入请求方法
import { getQusetionList, submitAnswer, reportInfo } from '@/api/index.js'
	export default {
		data() {
			return {
				navTitle: '答题栏',
				// displayPopup: false,
				surveryId: '',
				questionList: [],
				initCurrentIndex: 0,
				swiperDuration: 250,
				resultObj: {
					score: 0,
					correct: 0,
					wrong: 0,
					time: '00:00:00',
					notDone: 0,
					total: 0,
				},
				weixinbar: true
			}
		},
		computed: {
			precentData() {
				var precent = ((this.initCurrentIndex + 1)/this.resultObj.total) * 100
				return precent.toFixed(0)
			},
		},
		/**
		 * 初始化生命周期方法
		 * @param {Object} options 路由参数
		 */
		async onLoad(options) {
			uni.showLoading({
				title: '加载中',
				mask: true,
				icon: "loading"
			})
			this.surveryId = options.id
			// this.getQuestionList(options.id)
			// #ifdef MP-WEIXIN
				this.weixinbar = true
			// #endif
			// #ifdef MP-TOUTIAO
				this.weixinbar = false
			// #endif
		},
		async onReady() {
			var questionId = uni.getStorageSync("currentQuestionId")
				var questions = await getQusetionList(questionId)
				this.questionList = questions.data.list
				uni.hideLoading()
				if(this.questionList.length<=0) {
					uni.showLoading({
						title: '该问卷没有题目',
						icon: 'errro',
						mask: true
					})
				}else {
					uni.setStorageSync('questionList', [])
					this.resultObj.total = this.questionList.length
					// 通过 ref 调用 swiper 组件中的 init 方法，进行数据的初始化
					this.$refs.swiperRef.init(this.questionList, this.initCurrentIndex)
					// 设置导航栏题号信息
					this.navTitle = `${this.initCurrentIndex + 1}/${this.resultObj.total}` + `答题中`
				}
			
				
		},
		filters: {
			/**
			 * 答题卡题号状态样式方法
			 * @param {Number} index 传入当前项题号索引
			 * @param {Array} topicIndex 传入题目索引
			 * @param {Array} list 传入题目数组
			 * @return {String} 返回匹配类型样式（当前/正确/错误）
			 */
			stateStyle: (index, topicIndex, list) => {
				let state = ''
				if (topicIndex === index) state = 'current'

				state = `${state} ${list[index].state || ''}`

				return state
			},
		},

		methods: {
			async getQuestionList(id) {
				let questions = await getQusetionList(id)
				this.questionList = questions.data.list
				uni.hideLoading()
				if(this.questionList.length<=0) {
					uni.showLoading({
						title: '该问卷没有题目',
						icon: 'errro',
						mask: true
					})
				}
					uni.setStorageSync('questionList', [])
					this.resultObj.total = this.questionList.length
					console.log(this.questionList, this.initCurrentIndex)
					// 通过 ref 调用 swiper 组件中的 init 方法，进行数据的初始化
					this.$refs.swiperRef.init(this.questionList, this.initCurrentIndex)
					
					// 设置导航栏题号信息
					this.navTitle = `${this.initCurrentIndex + 1}/${this.resultObj.total}` + `答题中`
				// })
			},
			/**
			 * 点击左上角返回图标方法
			 */
			onClickBack() {
				uni.showModal({
					content: '是否确定要退出训练',
					success: res => {
						if (res.cancel) return
						uni.reLaunch({
							url: '/pages/index/index',
						})
						uni.removeStorageSync("optionsList")
					},
				})
			},

			/**
			 * swiper 切换事件
			 * @param {Object} e swiper 切换时产生的事件对象
			 */
			swiperChangeEvent(e) {
				this.initCurrentIndex = e.current
				this.navTitle = `${this.initCurrentIndex + 1}/${this.resultObj.total}` + `答题中`
			},

			/**
			 * 点击上一题方法
			 */
			onClickPrevious() {
				this.initCurrentIndex = this.initCurrentIndex - 1
			},

			/**
			 * 点击答题卡方法
			 */
			// onClickAnswerSheet() {
			// 	this.displayPopup = true
			// },

			/**
			 * 点击下一题方法
			 */
			onClickNext() {
			const myAnswer = this.questionList[this.initCurrentIndex].myAnswer
			if(myAnswer){
			  this.initCurrentIndex = this.initCurrentIndex + 1
			}else {
				uni.showToast({
					title: '请先完成当前题的回答',
					mask: true,
					icon: 'error'
				})
			}
			},

			/**
			 * 点击提交答案方法
			 */
			onClickSubmit() {
				this.questionList = uni.getStorageSync("questionList")
				var options = []
				for(let i = 0; i < this.questionList.length; i++) {
					options.push({
						question_id: this.questionList[i].questionId,
						score: this.questionList[i].currentScore,
						option_id: this.questionList[i].selectId,
						question_num: i+1
					})
				}
				var params = { 
					questionnaire_id: this.surveryId,
					options,
				}
				uni.showModal({
					content: '是否确定提交答案？',
					success: res => {
					  if (res.cancel) return
						//调取接口
						submitAnswer(params).then(res => {
							uni.removeStorageSync("questionList")
							uni.navigateTo({
								url: `/pages/report/index?surveryId=${this.surveryId}`
							})
						})
					},
				  })

			},

			/**
			 * 题目选项选择后回调函数
			 * @param {Object} state
			 */
			postSelectCallBack(data) {
				// this.answerSubtotal(state)
				this.questionList[data.index] = data.data
			},

			/**
			 * 答题小计方法
			 * @param {String} state 传入题是否正确状态
			 */
			answerSubtotal(state) {
				const resultObj = this.resultObj

				// 计算正确题目与错误题目的数量，正确则对题数量 +1
				if (state === 'correct') {
					resultObj.correct++
					this.onClickNext()
				} else {
					resultObj.wrong++
				}
				// 计算未做题目数量
				resultObj.notDone = resultObj.total - (resultObj.correct + resultObj.wrong)

				// 暂定：得分与正确题目数量保持一致
				resultObj.score = resultObj.correct
			},
		},
	}
</script>

<style lang="scss" scoped>
	.test-container {
		display: flex;
		flex-direction: column;
		width: 100vw;
		height: 100vh;
		overflow: hidden;

		.content-container {
			height: 100%;
		}

		.button-container {
			flex: 1;
			display: flex;
			align-items: center;
			height: 90rpx;
			margin-bottom: 40rpx;
			button {
				width: 100%;
			}
		}

		/* 答题卡面板区域样式 */
		.answer-sheet-container {
			display: flex;
			flex-direction: column;
			align-items: center;
			width: 100%;
			font-size: 28rpx;
			line-height: 28rpx;

			.answer-sheet-title {
				padding: 40rpx;
			}

			.scroll-view-container {
				box-sizing: border-box;
				display: flex;
				flex-wrap: wrap;
				align-content: flex-start;
				width: 100%;
				height: 620rpx;
				padding: 20rpx;

				.scroll-view-item {
					position: relative;
					display: flex;
					align-items: center;
					justify-content: center;
					width: 64rpx;
					height: 64rpx;
					border: 1px solid #bdc3c7;
					margin: 0 11rpx 20rpx 11rpx;
					border-radius: 100%;

					.iconfont-item {
						position: absolute;
						top: -10rpx;
						right: -4rpx;
						font-size: 28rpx;
						color: #f1c40f;
					}
				}
			}

			/* 答题面板底部描述区域样式 */
			.answer-sheet-desc {
				display: flex;
				align-items: center;
				justify-content: space-around;
				width: 100%;
				height: 80rpx;

				.answer-sheet-desc-item-container {
					display: flex;
					align-items: center;
					font-size: 28rpx;
					line-height: 28rpx;

					.answer-sheet-desc-item-mark {
						width: 28rpx;
						height: 28rpx;
						border: 1px solid #bdc3c7;
						margin-right: 10rpx;
						border-radius: 100%;
					}
				}
			}

			/* 提交答案区域样式 */
			.submit-btn {
				width: 90%;
				padding: 20rpx 0;
				margin-bottom: 20rpx;
				font-size: 32rpx;
				line-height: 32rpx;
			}
		}
	}
</style>